window.DOSIK=window.DOSIK||{};DOSIK["ip_1"]={"1":[{"t":"tree","title":"지식재산의 개념","root":"지식재산","branches":[["지식재산 기본법","지식재산에 관한 정책을 통일된 원칙으로 추진하기 위한 「지식재산 기본법」은 2011년 5월에 제정되었다 · 지식재산을 창출, 활용, 보호의 세 단계로 구분한다"],["지식재산","인간의 창조적 활동이나 경험으로 창출·발견된 지식, 정보, 기술, 표현, 표시 등으로서 재산적 가치가 실현될 수 있는 것을 말한다"],["지식재산권","법령 또는 조약 등에 따라 인정되거나 보호되는 지식재산에 관한 권리를 말한다"],["무형자산","지식재산은 무형자산이며, 하나의 제품이 여러 종류의 지식재산권으로 동시에 보호받을 수 있다"]]},{"t":"table","title":"국제기구","head":["기구","내용"],"rows":[["IP5","한국, 미국, 중국, 일본, 유럽연합의 5개 특허청 협의체로 전 세계 특허출원의 90% 이상을 차지하며 2007년에 출범했다"],["WIPO","지식재산 정책과 제도를 논의하는 UN 전문기구로 본부는 스위스 제네바에 있다 · 설립 협약은 1967년 스톡홀름에서 채택되었고 1970년 4월에 공식 설립되었다"],["WIPO의 기능","파리협약, 특허협력조약, 베른협약 등의 조약 관리와 국제 출원 서비스 제공, 글로벌 혁신지수 발표 등의 기능을 한다"]]},{"t":"tree","title":"지식재산권의 구분","root":"지식재산권","branches":[["산업재산권","산업상 이용가치를 갖는 권리로 특허권, 실용신안권, 디자인권, 상표권이 포함된다"],["저작권","문화 영역 보호를 본질로 한다"],["신지식재산권","새로운 분야에서 나타나 기존 산업재산권으로 보호받지 못하는 지식재산에 대한 권리이다"]]}],"2":[{"t":"table","title":"산업재산권의 존속기간","head":["구분","내용"],"rows":[["특허권","설정등록일부터 발생하여 특허출원일 후 20년까지 존속한다 · 허가 등으로 발명을 실시하지 못했거나 심사가 지연되어 등록된 경우 특허권의 존속기간 연장이 가능하다"],["실용신안권","물품의 형상, 구조, 조합에 관한 고안만 보호하므로 물질발명이나 방법발명은 보호받을 수 없다 · 설정등록일부터 발생하여 실용신안등록출원일 후 10년이 되는 날까지 존속한다"],["디자인권","설정등록일부터 발생하여 디자인등록출원일 후 20년이 되는 날까지 존속한다 · 디자인은 물품의 형상, 모양, 색채 또는 이들의 결합으로서 시각을 통해 미감을 일으키게 하는 것이다 · 원칙적으로 심사 후 등록되지만 무심사 등록제도의 예외가 있다"],["상표권","설정등록일부터 10년간 존속하며 갱신등록신청으로 10년씩 갱신할 수 있다 · 상표법상 표장에는 기호, 문자, 도형, 소리, 냄새, 입체적 형상 · 홀로그램, 동작, 색채 등이 포함된다"]]},{"t":"def","term":"출원 관할","text":"특허, 실용신안, 디자인, 상표의 출원은 모두 특허청이 관할하며 심사 후 등록으로 권리가 발생한다"}],"3":[{"t":"tree","title":"저작권","root":"저작권","branches":[["발생","별도의 출원이나 등록 절차 없이 저작물을 창작한 때부터 자동으로 발생한다"],["저작인격권","공표권, 성명표시권, 동일성유지권으로 구성되며 양도할 수 없다"],["저작재산권","복제권, 공연권, 방송권, 전시권, 배포권, 2차적저작물작성권 등으로 양도, 판매, 라이선스가 가능하다"],["존속기간","저작자의 생존 기간과 사망 후 70년 동안 존속한다"]]},{"t":"tree","title":"저작인접권","root":"저작인접권","branches":[["권리자","실연자, 음반제작자, 방송사업자에게 부여되는 권리이다"],["존속기간","일반적으로 공연, 녹음 또는 방송일로부터 50년이다"]]}],"4":[{"t":"tree","title":"영업비밀","root":"영업비밀","branches":[["핵심","비밀 유지, 경제적 가치, 비밀 유지를 위한 합리적 노력이다"],["정의","「부정경쟁방지 및 영업비밀보호에 관한 법률」에 규정되어 있다"],["요건","비밀관리기간 동안 보호되며 비공지성 · 경제적 유용성, 비밀관리성을 요건으로 한다"]]},{"t":"vs","title":"특허와 영업비밀","cols":[{"name":"특허","items":["독점권의 대가로 발명의 공개를 요구한다","산업재산권에는 존속기간이 있다"]},{"name":"영업비밀","items":["공개를 요구하지 않는다","비밀로 유지되고 경제적 가치가 있는 한 이론상 무기한 존속할 수 있다","특허청 등에 대한 공식적인 등록 절차가 없다"]}]}],"5":[{"t":"tree","title":"데이터베이스","root":"데이터베이스","branches":[["편집저작물","소재의 선택·배열 등에 창작성이 있으면 편집저작물로 보호될 수 있다"],["제작자의 권리","제작 완료 때부터 발생하여 그 다음 해부터 5년간 존속한다"],["갱신","갱신 등에 상당한 투자가 이루어진 경우 그 부분의 제작자 권리는 갱신한 때부터 발생해 다음 해부터 5년간 존속한다"],["도입","데이터베이스 제작자의 권리는 창작성 수준과 관계없이 제작 노력을 보호하기 위해 2003년 저작권법에 도입되었다"]]},{"t":"tree","title":"컴퓨터프로그램","root":"컴퓨터프로그램","branches":[["저작권","문학저작물로 간주되어 저작권으로 보호받을 수 있다 · 데이터베이스와 전화기 ROM에 기록된 프로그램은 저작권법 적용 대상이며 창작과 동시에 권리가 발생한다"],["특허","컴퓨터프로그램 자체는 발명에 해당하지 않아 특허받기 어렵지만 저장 매체나 구동 장치·방법으로 청구하면 특허권으로 보호될 수 있다 · 기술 발명에 해당하는 컴퓨터프로그램은 특허법으로 보호되며 심사 후 등록되어 출원 후 20년간 보호된다"]]},{"t":"tree","title":"반도체 배치설계","root":"반도체 배치설계","branches":[["존속기간","반도체 배치설계권은 설정등록일부터 10년간 존속하되 최초 영리 이용일부터 10년 또는 창작일부터 15년을 초과할 수 없다 · 등록 후 10년간 보호된다"],["등록","등록을 요건으로 하지만 실체 심사는 하지 않는다 · 심사 없이 등록만으로 권리가 발생한다"],["설정등록 신청","배치설계 창작자는 영리 목적으로 최초 이용한 날부터 2년 이내에 설정등록을 신청할 수 있다"]]}],"6":[{"t":"tree","title":"품종보호","root":"식물 품종","branches":[["요건","식물 품종이 품종보호권을 받으려면 신규성, 구별성, 균일성, 안정성을 갖추어야 한다"],["존속기간","품종보호권은 설정등록일부터 20년간 존속하며 과수와 임목은 25년이다"],["독점","품종보호권자는 업으로서 보호품종을 실시할 권리를 독점한다"],["소관","식물 신품종은 농림축산식품부 소관이며 심사 후 등록된다"]]},{"t":"tree","title":"유전자원","root":"유전자원","branches":[["유전자원","식물, 동물, 미생물 등 유전적 기원이 되는 유전물질 중 실질적 또는 잠재적 가치를 지닌 물질을 말한다"],["전통지식","유전자원의 보전과 지속가능한 이용에 적합한 생활양식을 유지해 온 개인이나 지역사회의 지식, 기술, 관행을 말한다"],["유전자원법","유전자원과 전통지식의 접근·이용에서 발생하는 이익을 공정하고 공평하게 공유하기 위한 사항을 정한다"],["주권적 권리","유전자원과 전통지식은 보유국의 주권적 권리로 본다"]]}],"7":[{"t":"table","title":"지식재산권의 기능","head":["기능","내용"],"rows":[["혁신 인센티브","발명가와 창작자에게 독점권을 주어 혁신과 창조에 대한 재정적 인센티브를 제공한다"],["창작 동기","창작자의 독창성을 인정하고 보상함으로써 현재와 미래 세대의 창작 동기를 유발한다"],["투자 회수","연구개발에 투입한 자원을 보호해 기업이 투자 수익을 회수할 수 있게 하며 벤처캐피탈 등 자금 유치에도 기여한다"],["불공정 경쟁 방지","타인의 창조물을 불법적으로 이용하지 못하게 하여 불공정 경쟁을 막고 상표는 위조품으로부터 소비자를 보호한다"],["경쟁 촉진","혁신과 창작물을 보호함으로써 새로운 기업의 시장 진입 장벽을 낮추고 경쟁을 촉진한다"],["특허 공개","특허법은 출원된 발명이 대중에게 공개되도록 하여 다른 발명가가 이를 학습해 새로운 혁신을 창출하게 한다"],["기술 이전","대학과 연구기관은 라이선스 계약으로 특허 기술을 기업에 이전해 연구 결과의 사업화를 촉진할 수 있다"],["경제 성장","강력한 지식재산권 체제는 GDP 기여 산업의 성장을 촉진하고 외국인 투자와 다국적 기업의 R&D 센터를 유치하는 데 도움이 된다"]]}],"8":[{"t":"table","title":"개별 법률의 목적","head":["법률","목적"],"rows":[["특허법","발명을 보호·장려하고 이용을 도모하여 기술의 발전을 촉진함으로써 산업발전에 이바지함을 목적으로 한다"],["실용신안법","실용적인 고안을 보호·장려하고 그 이용을 도모하여 기술의 발전을 촉진함으로써 산업발전에 이바지함을 목적으로 한다"],["디자인보호법","디자인의 보호와 이용을 도모하고 디자인의 창작을 장려하여 산업발전에 이바지함을 목적으로 한다"],["상표법","상표를 보호하여 상표 사용자의 업무상 신용 유지를 도모하고 수요자의 이익을 보호함을 목적으로 한다"],["저작권법","저작자의 권리와 인접하는 권리를 보호하고 저작물의 공정한 이용을 도모하여 문화 및 관련 산업의 향상발전에 이바지함을 목적으로 한다"],["반도체설계법","반도체집적회로의 배치설계에 관한 창작자의 권리를 보호하고 배치설계를 공정하게 이용하게 하여 국민경제의 건전한 발전에 이바지함을 목적으로 한다"],["부정경쟁방지법","국내에 널리 알려진 타인의 상표·상호 등의 부정 사용 같은 부정경쟁행위와 영업비밀 침해행위를 방지하여 건전한 거래질서를 유지함을 목적으로 한다"],["식물신품종보호법","식물 신품종에 대한 육성자의 권리 보호를 규정하여 농림수산업의 발전에 이바지함을 목적으로 한다"],["유전자원법","나고야 의정서의 시행에 필요한 사항과 유전자원 및 전통지식 이용 이익의 공정하고 공평한 공유를 정하여 생물다양성 보전과 지속가능한 이용에 기여함을 목적으로 한다"]]}],"9":[{"t":"tree","title":"보호 전략","root":"아이디어 창작자의 보호 전략","branches":[["선택","보호 전략으로 공개, 노하우, 특허 세 가지 중 하나를 선택할 수 있다"],["공개","경쟁자에 의한 선점 특허를 예방하는 데 목적이 있어 공개 시점과 내용을 명확히 해야 한다"],["노하우","제조방법처럼 노하우로 보호하려면 영업비밀 요건의 충족 관리와 선사용권 요건의 충족이 필요하다"],["특허","아이디어를 특허로 보호하려면 발명의 성립성 등 등록요건을 갖추어야 한다"]]},{"t":"table","title":"스마트폰의 중복 보호","head":["대상","보호"],"rows":[["기술","특허"],["시각적 디자인","디자인권"],["브랜드","상표"],["소프트웨어","저작권"]]},{"t":"def","term":"발명","text":"특허법상 발명은 자연법칙을 이용한 기술적 사상의 창작으로서 고도한 것이다 · 발명으로 인정되려면 자연법칙을 활용하고, 실용적 결과를 달성하는 기술적 아이디어여야 하며, 기존 기술을 크게 향상시키는 고차원적 창작성이 있어야 한다"}],"10":[{"t":"tree","title":"인터넷 기술공지","root":"인터넷 기술공지","branches":[["공개 전략","공개는 아이디어를 선행기술로 확립해 다른 사람이 특허출원하는 것을 막을 수 있는 방어적 전략이다"],["입증","창작자는 타인의 특허출원 이전에 자신의 아이디어가 공개되었음을 입증해야 하며 특허청의 인터넷 기술공지 시스템을 활용할 수 있다"],["방식","기술 내용과 신뢰할 수 있는 날짜 정보를 게시해 특허청이 공개 사실을 공증하고 인정하는 방식이다"],["이용 방법","특허청 사이트에서 사이버 공지를 신청하고 공지 자료실에 공개를 원하는 기술 내용을 등록하는 방식으로 이용한다"]]},{"t":"vs","title":"인터넷 기술공지의 이용","cols":[{"name":"이용하면 효과적","items":["방어 목적의 출원, 공공기관의 공증이 필요한 법적 대응, 기술 동향 파악이 필요한 경우"]},{"name":"이용하지 않아야 함","items":["특허권을 행사하려는 경우나 영업비밀로 보호해야 할 기술"]}]}],"11":[{"t":"def","term":"노하우","text":"비밀로 유지되는 특정 작업이나 프로세스 수행에 필요한 실질적 지식과 기술이다 · 공개를 요구하는 특허와 달리 비밀로 보호된다"},{"t":"table","title":"특허와 노하우의 비교","head":["항목","특허","노하우"],"rows":[["보호 기간","특허는 일반적으로 출원일로부터 20년 보호된다","노하우는 비밀이 유지되는 한 무기한 보호될 수 있다"],["공개","출원을 통해 발명이 공개된다","비밀로 유지된다"],["비용","출원·유지·시행 비용이 높은 편이다","비용이 저렴하며 비밀 유지에 중점을 둔다"],["경쟁우위","대중의 인정을 받아 한시적 경쟁우위를 제공한다","비밀이 유지되면 장기적 경쟁우위를 제공할 수 있다"],["라이선스","명확한 법적 권리가 있는 특허는 라이선스와 파트너십이 촉진된다","비밀을 공개하지 않고 라이선스를 취득하기가 더 어렵다"],["권리 집행","명확한 법적 권리가 있다","권리 집행 가능성은 기밀 유지 위반을 입증하는 능력에 따라 달라진다"]]}],"12":[{"t":"cause","title":"선사용권의 취지","causes":["노하우로 보호하던 아이디어를 제3자가 특허받으면 침해가 생길 수 있다"],"result":"선사용 사실이 인정되는 자에게 무상의 통상실시권인 선사용권을 부여한다"},{"t":"tree","title":"선사용권","root":"선사용권","branches":[["근거","선사용에 의한 통상실시권은 특허법 제103조에 근거한다"],["인정 대상","타인의 특허출원 전에 국내에서 그 발명을 실시하는 사업 또는 사업 준비를 하고 있었던 자에게 인정된다"],["증거 확보","선사용권을 주장하기 위해서는 설계도, 발주서류 등을 보존하거나 공증제도를 활용해 선사용에 대한 증거를 확보해 두어야 한다"]]}],"13":[{"t":"vs","title":"통상실시권과 전용실시권","cols":[{"name":"통상실시권","items":["비독점 라이선스로 여러 명의 실시권자가 있을 수 있다 · 특허권자도 특허를 사용하며 추가 라이선스를 줄 수 있다"]},{"name":"전용실시권","items":["특정 지역이나 특정 목적으로 사용할 수 있는 유일한 권리 · 실시권자에게 부여하는 독점 라이선스이다","특허법 제100조에 규정되어 있다","설정하면 특허권자는 합의된 범위 내 · 에서 같은 발명에 대해 추가 라이선스를 줄 수 없다 · 발명품도 사용할 수 없다"]}]}],"14":[{"t":"tree","title":"지식재산 경영","root":"지식재산 경영","branches":[["정의","특허·실용신안·디자인·상표·영업비밀 등을 기업의 자산으로 활용하는 경영전략으로 수익을 창출해 기업 가치를 높이는 활동이다 · 특허청의 지식재산경영인증 운영 요령에 기술되어 있다"],["활동","R&D 성과물에 배타적 권리를 확보하거나 자산화하고 이를 활용·활성화해 경제적 부가가치를 창출하려는 전략적 활동이다"],["목적","주요 경영 의사결정에 지식재산을 활용해 기업의 본질적 가치를 높이거나 새로운 부가가치를 창출하는 것이다"],["IP R&D 전략","글로벌 경쟁력을 확보한 강한 지식재산 창출과 확보된 지식재산의 활용·확산을 통한 부가가치 극대화로 연계되어야 한다"],["전략의 연계","경영전략, R&D 전략, IP경영전략은 서로 연계되어 성과를 창출하고 이를 통해 경영목표를 달성한다"]]}],"15":[{"t":"vs","title":"창출 단계와 활용 단계","cols":[{"name":"창출 단계","items":["기업의 R&D 기획 단계부터 시작해 신규 발명의 권리화 업무까지 포함한다","지식재산 담당자는 직무발명제도를 수립하고 직무발명심의위원회를 운영하며 선행기술 검색과 분석으로 신기술 동향을 파악해야 한다"]},{"name":"활용 단계","items":["기업은 M&A, 라이선스 계약, 소송 전략 수립 등에 지식재산권을 활용하며 경쟁사의 R&D 전략과 보유 기술의 잠재 경쟁력을 분석한다"]}]},{"t":"def","term":"직무발명","text":"고용 계약을 통해 기업에 종사하는 종업원이 직무 수행 과정에서 창출한 발명을 직무발명이라고 한다"},{"t":"tree","title":"지식재산 경영의 운영","root":"지식재산 경영","branches":[["단계 연계","크게 창출 단계와 활용 단계로 구분하며 두 단계가 유기적으로 연계되도록 운영해야 한다"],["전담 조직","경쟁사와의 지식재산권 분쟁이 잦은 수출기업은 지식재산권을 전담하는 조직을 신설할 필요가 있으며 내부 역량이 부족하면 외부 전문가를 활용한다"]]}],"16":[{"t":"def","term":"특허 경영","text":"특허를 중요한 경영자원으로 보고 개발·생산·판매 프로세스와 결합해 기업의 경쟁력을 확보하는 경영방식이다 · 경쟁사의 진입을 견제·지연시키고 고객 만족도와 시장 점유율을 높여 이익 극대화를 추구할 수 있다"},{"t":"tree","title":"삼위일체 전략","root":"삼위일체 전략","branches":[["모형","사업전략, 연구개발전략, 특허전략을 연동해 추진할 때 가장 효과적인 성과를 창출한다는 모형이다"],["특허전략 구축","특허로 출원할지 영업비밀로 관리할지 판단하고, 선택과 집중으로 질적 성장을 꾀하며, 특허맵으로 타사 동향을 조사한다"]]},{"t":"tree","title":"특허정보의 활용","root":"특허정보","branches":[["사업 판단","신규 사업시장 진출과 타사와의 사업 제휴 판단재료로 활용되며 공격·방어·예방 측면에서 권리를 확보한다"],["기술 판단","자사의 기술력 분석, 연구개발 주제 설정, 공동연구개발 파트너 선정의 판단재료로 활용된다"]]}],"17":[{"t":"def","term":"특허 경영 발전 모형","text":"Davis와 Harrison의 특허 경영 발전 모형은 방어적, 비용 절감, 수익 창출, 통합, 고도화의 5단계로 구분된다 · 특허 경영 5단계는 Level 1 방어적, Level 2 비용 절감, Level 3 수익 창출, Level 4 통합, Level 5 고도화 순으로 발전한다"},{"t":"flow","title":"특허 경영 5단계","steps":["Level 1 방어적 단계는 지식재산권 창출·보호 전략을 세워 경쟁사의 침해와 소송으로부터 기업을 방어하는 가장 기초 단계이다 · 비즈니스 모델의 안정성과 독점성을 위해 특허를 많이 출원·획득해 포트폴리오를 구축하며 사내 지식재산권 선순환 구조를 만든다","Level 2 비용 절감 단계는 지식재산권 확보·유지·관리 비용을 절감하고 효율적인 확보 방법을 고민하며 포트폴리오를 구축하는 단계이다 · 비용 절감 목표를 설정하는 것이 가장 기본적인 방법이며 보유 효과를 평가하기 위한 가치평가를 진행할 수도 있다","Level 3 수익 창출 단계는 지식재산권을 활용해 경쟁 우위를 선점하거나 라이선스 계약 등으로 수익을 실현하는 단계이다 · 수익을 창출할 수 있는 전담 조직과 전문가의 자문이 필요하다","Level 4 통합 단계는 지식재산권을 경영 자산으로 인식하고 경영전략과 지식재산권 활용 전략을 통합하여 절세 수단이나 M&A 등에도 활용하는 단계이다 · 경쟁사의 지식재산권을 주기적으로 분석해 마케팅 전략을 수정하고 인사 부서는 지식재산권 전문인력을 채용한다","Level 5 고도화 단계는 지식재산권 전략이 조직 내에 깊이 자리 잡아 산업 동향과 소비자 선호의 미래 흐름을 조사·분석하는 데 지식재산을 활용하는 단계이다"]}],"18":[{"t":"vs","title":"브랜드와 상표","cols":[{"name":"브랜드","items":["판매자나 제조업자가 자신의 상품·서비스를 경쟁자의 것과 구별하도록 표시하는 이름, 문자, 기호, 슬로건, 캐릭터, 디자인 등이다","마케팅적 개념이다"]},{"name":"상표","items":["법적 개념이며, 브랜드를 법적으로 보호받는 좁은 의미의 영역이다","좁은 의미의 브랜드 상표에는 상호 상표(기업마크 포함)와 상품 상표(Pet Name)가 있다"]}]},{"t":"tree","title":"브랜드 경영","root":"브랜드 경영","branches":[["정의","브랜드를 기업 자산의 중요한 항목으로 인식하고 전략적으로 개발·관리·보호하여 경쟁력을 유지하고 장기적으로 기업 가치를 창출하는 과정이다"],["효과","성공적인 브랜드 경영은 기업 실적을 개선하고 고객 충성도를 높이며 경쟁사의 시장 진입 장벽을 높인다"],["수익","기술이 상향평준화되어 품질이 대동소이하더라도 소비자는 브랜드를 통해 형성된 신뢰와 기대로 제품을 선택하므로 브랜드는 기업 수익과 직결된다"]]},{"t":"tree","title":"브랜드 자산의 가치","root":"브랜드","branches":[["자산 가치","1980년대 미국과 유럽에서 M&A가 빈번할 때 브랜드 가치를 화폐 금액으로 환산해 대차대조표에 계상하면서 자산으로서 가치를 가지기 시작했다"],["핵심 자산","글로벌 경쟁이 치열해지면서 브랜드는 단순한 식별 수단을 넘어 소비자와 기업의 신뢰를 구축하고 차별화된 가치를 전달하는 핵심 자산이 되었다"],["OEM 방식","초기에는 안정적 시장 진입에 유리하지만 장기적으로 낮은 단가에 따른 수익률 제한, 구매자의 잦은 이탈, 고객 인지도 실패 등의 한계가 있다"]]},{"t":"tree","title":"상표 분쟁 예방","root":"브랜드 기획","branches":[["상표법 확인","브랜드 기획 단계부터 상표법을 확인하고 선등록 상표를 반드시 검색해야 상표 출원 후 법적 분쟁을 예방할 수 있다"],["선등록 상표","선등록 상표 때문에 상표 등록을 받을 수 없다면 무효심판 또는 취소심판 청구 등으로 보호받을 전략을 준비해야 한다"]]}],"19":[{"t":"def","term":"디자인","text":"디자인의 어원은 '지시하다' 또는 '계획하다'를 뜻하는 라틴어 designare이며 이탈리아어 disegno를 거쳐 발전했다"},{"t":"tree","title":"디자인 경영","root":"디자인 경영","branches":[["개념","기업이 디자인 관련 의사결정을 할 때 시장 상황과 고객 중심으로 접근하여 기업의 전략적 목표를 달성하는 수단으로 삼는 방법이다"],["최초의 정의","1996년 영국의 디자인 컨설턴트 마이클 파가 내렸다"],["필요성","소비자는 가격·품질·기능뿐 아니라 경쟁력 있는 디자인을 보고 제품과 서비스를 선택하므로 경영 활동 전 과정에 디자인에 대한 관심과 협조가 필요하다"],["사례","애플의 아이팟은 음악 재생 외의 부가 기능을 줄이고 조작의 단순성을 표준으로 만들어 디자인 경영의 성과를 보여준 대표 사례이다"]]},{"t":"tree","title":"디자인 분쟁 예방","root":"디자인 경영","branches":[["관리 범위","디자인의 창출, 등록, 보호와 분쟁 예방까지 관리하는 것으로 창작 과정에서 선 등록 유사 디자인을 검색하고 디자인보호법을 확인한 후 출원해야 한다"],["선 등록 디자인","선 등록 디자인 때문에 자사 디자인을 등록받지 못하거나 권리 획득이 어려우면 독점적 권리가 약해지므로 디자인 선정 단계에서 먼저 인지해 수정·보완해야 한다"],["권리 확보","확보하려는 디자인과 주변 디자인까지 미리 권리로 확보하는 것이 좋다"]]}],"20":[{"t":"tree","title":"지식재산 경영의 핵심과제","root":"지식재산 경영의 핵심과제","branches":[["핵심과제","지식재산의 경영자원화와 지식재산권 리스크 매니지먼트이다"],["경영자원화","경영자원의 창출, 강한 지재권 확보, 경영 전략적 활용이 포함된다"]]},{"t":"tree","title":"강한 특허","root":"강한 특허","branches":[["정의","경쟁사가 쉽게 침해할 수 없고 권리를 효과적으로 행사할 수 있는 특허이며 원천기술·핵심기술이나 표준특허가 이에 해당한다"],["확보 방법","선행기술을 조사·분석하고 지속적인 R&D와 이에 따른 지식재산권 창출이 필요하다"],["활용","특허, 디자인, 브랜드 등 일정 규모의 지식재산권을 확보하면 포트폴리오를 구축해 전략적으로 활용하고 라이선스나 판매로 수익을 창출할 수 있다"]]}],"21":[{"t":"tree","title":"지식재산권 리스크 매니지먼트","root":"지식재산권 리스크 매니지먼트","branches":[["포함","지재권 분쟁 예방, 분쟁 방어, 특허료의 최소화가 포함된다"],["핵심","위험 요소를 사전에 예측하고 대책을 세워 예측 가능한 리스크를 제거하는 것이다"]]},{"t":"table","title":"지식재산권 분쟁 리스크","head":["리스크","내용"],"rows":[["리스크의 종류","시장 진입 장벽, 사업 중단 사태, 판매 영향, 바이어의 특허 보증 요구, 특허료 부담, 소송·손해배상 비용 증대가 있다"],["사업 중단 사태","지식재산권 분쟁으로 가처분이 인용되면 판매가 중지되고 투자가 무용해지는 사업 중단 사태가 발생할 수 있다"],["바이어의 특허 보증 요구","바이어가 특허 보증을 요구하면 분쟁이 해결될 때까지 거래가 보류될 수 있다"]]}],"22":[{"t":"table","title":"경쟁력 요소와 권리","head":["요소","내용"],"rows":[["기술","권리 측면에서 특허권에 대응한다 · 우수한 품질의 제품에 적용되는 기술이 특허로 보호받을 때 제품의 경쟁력이 강화된다 · 기업이 기술 개발에 소홀해 경쟁 기업의 기술을 도입하면 라이선스 비용으로 제품 원가가 상승하고, 경쟁사가 사용을 허락하지 않으면 신제품 개발이 어려워진다"],["디자인","권리 측면에서 디자인권에 대응한다 · 유사한 디자인이 등장하면 자사의 디자인 경쟁력이나 판매 점유율이 낮아지므로 디자인의 등록과 관리가 필요하다"],["브랜드","권리 측면에서 상표권에 대응한다 · 자사의 브랜드를 관리·유지하는 것은 제품의 경쟁력 확보에 중요하며 유사상표의 출현이나 타인의 등록상표 침해 위험에 대비해야 한다"]]},{"t":"tree","title":"지식재산권의 마케팅 효과","root":"지식재산권","branches":[["선순환","지식재산권이 도입되면 좋은 상품 개발(상품 경쟁력), 판매·영업(마케팅 경쟁력), 이익의 극대화(손익 경쟁력)가 서로 선순환하는 구조가 만들어진다"],["긍정적 효과","사업의 보호, 제품 시장의 독점, 브랜드 마케팅 지원, 신규 시장 진출 가능이라는 긍정적 마케팅 효과가 있다"],["진입 차단","경쟁사의 시장 진입을 합법적으로 차단하거나 지연시키는 유일한 수단이 지식재산권이다"],["경쟁사 배제","합법적으로 경쟁사를 배제하는 수단이 되기도 하고, 독보적 기술을 확보하면 큰 어려움 없이 시장에 진출할 수 있게 하는 도구이다"]]},{"t":"tree","title":"지식재산권 활용 사례","root":"사례","branches":[["마이크로소프트","타사의 유용한 특허를 매입해 포트폴리오를 강화하고 이를 무기로 경쟁사의 진입을 막는 전략을 구사해 왔다"],["OEM 방식","유명 회사의 브랜드로 시장에 진출하기 쉽지만 자사 브랜드를 독자적으로 홍보하기 어렵고 주문자의 마케팅에 종속되므로 장기적으로 벗어나야 한다"]]}],"23":[{"t":"vs","title":"독점과 라이선스","cols":[{"name":"독점","items":["공급자가 독점이면 가격 결정에 큰 영향력을 행사할 수 있다"]},{"name":"라이선스 허용","items":["독점하지 않고 라이선스를 허용하면 이윤이 줄어도 라이선스 수입이 증가한다"]}]},{"t":"tree","title":"특허료 수익","root":"특허료 수익","branches":[["표준특허","확보한 특허가 국제 표준 기술이라면 표준특허 풀에 가입해 안정적인 특허료 수익을 창출할 수 있다"],["표준특허가 아닌 경우","상대방이 자사 특허를 침해했다는 근거를 확보하고 지식재산권 소송 전략을 수립해야 하며 완벽히 준비된 경우에만 특허료 수익 창출에 성공할 수 있다"]]},{"t":"tree","title":"비용과 가치평가","root":"지식재산권","branches":[["출원·등록 비용","자산 취득 항목으로 관리된다"],["분쟁 비용","지식재산권 분쟁에 필요한 비용은 경비로 지출한다"],["라이선스 비용","기업은 경쟁사의 지식재산권이 자사 제품에 사용되는지 검토해 라이선스 비용을 원가에 반영해야 하며, 독점적 기술일수록 비싼 라이선스 비용을 지급해야 한다"],["가치평가","M&A, 매각 또는 담보 제공 시에도 가치를 평가받을 수 있으며 코카콜라의 브랜드 가치는 순 유형자산의 5배 이상으로 평가된 바 있다"]]}],"24":[{"t":"table","title":"지식재산권 관리 4단계","head":["단계","내용"],"rows":[["1단계 행정 관리","기술 도입기로 특허 전담자가 없고 분쟁은 전문가에게 위탁하며 특허출원 행정 관리를 하는 수준이다"],["2단계 특허 관리","특허 도입기로 특허 전담자를 두고 특허출원과 분쟁을 방어 중심으로 관리한다"],["3단계 전문화","기술 개발기로 특허 전담 조직과 전략적 특허출원이 있으며 분쟁에서 방어가 공격보다 큰 비중을 차지한다"],["4단계 특허 경영","기술 독립기로 특허의 경영자원화, 특허 포트폴리오 운영, 특허료 수지 관리 · 분쟁에서 공격이 방어보다 큰 비중을 차지한다"]]},{"t":"flow","title":"기업의 지식재산권 관리","steps":["행정 관리","특허 관리","전문화","특허 경영"]}],"25":[{"t":"tree","title":"1단계 대응 전략","root":"1단계","branches":[["외부 위탁","외부 전문 기업(관)에 위탁하고 행정 관리만 하되 장기적으로 전담자를 발굴·육성하며 도입 기술의 특허를 분석해 회피 가능하면 라이선스 비용을 절감한다"],["브랜드 관리","브랜드 관리가 업무의 중심이 되므로 미리 상표권을 확보하고 국내 및 수출 국가에 선등록된 상표가 있는지 지속적으로 모니터링해야 한다"]]},{"t":"tree","title":"2단계 대응 전략","root":"2단계","branches":[["라이선스","특허 라이선스의 필요성을 검토하고 계약 종료에 대비해 회피 기술 개발과 특허출원을 준비하며 OEM 공급 경험 기업은 사전에 특허 침해 가능성을 검토해야 한다"],["특허맵","자사 제품과 기술에 대한 특허맵을 작성하고 경쟁사의 지식재산권 현황을 파악해 기술 개발 방향을 설정한다"],["포트폴리오","직무발명보상제도를 운영하고 사소한 발명도 출원해 포트폴리오를 구축하며 디자인 개발 시 선행 디자인을 반드시 조사한다"]]}],"26":[{"t":"tree","title":"3단계 대응 전략","root":"3단계","branches":[["전담 조직","전담 조직이 선행 기술·디자인을 지속적으로 검색·분석해 연구원에게 제공하여 R&D 효율화를 추구하고 분쟁에 주도적으로 대응한다"],["교육","지식재산권 교육과 전문 인력 육성 프로그램을 운영하고 출원 양도 중요하지만 결국 질 중심의 관리가 이루어져야 강력한 포트폴리오를 구축할 수 있다"],["아웃소싱","전문 인력 육성·확보에는 한계가 있으므로 3단계에서도 외부 전문 기업(관)에 대한 아웃소싱을 적절히 활용해야 한다"]]},{"t":"tree","title":"4단계 대응 전략","root":"4단계","branches":[["경영자원","지식재산권이 경영자원으로 활용되도록 사업 전략과 연계하고 질 중심으로 구성하며 해외 지식재산권 확보와 외부 특허 매입도 병행한다"],["전담 조직","외부 법률사무소와 긴밀히 협력하되 분쟁 전체를 관리하고 의사결정을 주도적으로 해야 하며 경쟁사 분쟁에 대한 사전 예측과 대응 체제를 준비해야 한다"],["수익 관리","지식재산권을 통한 수익 창출과 수지 관리를 경영 지표의 하나로 관리하고 핵심특허나 국제 표준특허를 확보해 수익을 극대화한다"]]}],"27":[{"t":"def","term":"지식재산경영인증","text":"지식재산 경영을 모범적으로 수행하는 기업의 자긍심을 높이고 대외 인지도를 제고하며 중소기업의 자발적인 지식재산 경영 도입을 유도하는 제도이다 · 지식재산 담당 조직 및 인력, 직무발명 활성화 등 총 10가지 항목을 심사하며 100점 만점에 70점 이상이면 인증된다"},{"t":"table","title":"심사항목의 배점","head":["항목","배점"],"rows":[["지식재산권 동향 파악 및 활용","배점이 가장 큰 항목으로 21점이다"],["지식재산 담당 조직 및 인력","10점"],["직무발명 활성화","5점"],["지식재산권 교육","5점"],["국내외 산업재산권 보유 건수","16점"],["국내외 산업재산권 출원 실적","8점"],["연구개발 인력 및 금액","12점"],["지식재산권 적용 제품 매출 비중","8점"],["실시권 등 활용","8점"],["분쟁 사전 점검","7점"]]}],"28":[{"t":"table","title":"인증 항목별 평가기준","head":["항목","기준"],"rows":[["지식재산 담당 조직 및 인력","지식재산권 관련 전담부서를 보유하면 10점이며 전담인력을 보유하면 인당 6점, 겸임인력은 인당 3점(최대 6점)이다"],["직무발명 활성화","보상 우수기업 선정 시 5점이며 그 외 기업은 보상규정 보유 2점과 최근 3년간 직무발명보상 활동에 따라 건당 점수를 부여한다"],["출원 실적","최근 2년 이내 건을 환산하며 특허권(실용신안 포함)만의 합계가 6점을 초과할 수 없다"],["보유 건수","환산에서 특허권(실용신안 포함), 상표권, 디자인권 각각의 환산 점수 합은 8점을 초과할 수 없다"],["특허분석평가시스템","보유 국내 특허권의 평가에서 AAA는 건당 1점, AA는 0.9점, A는 0.7점, BBB는 0.5점, BB는 0.3점, B는 0.1점이며 최대 5점이다"],["지식재산권 교육","최근 2년간 자체 개최 1건당 1.5점, 외부 교육 참석 1건당 1점으로 환산해 합산한다"]]},{"t":"table","title":"연구개발·동향·매출·실시권·분쟁","head":["항목","기준"],"rows":[["연구개발 인력","15인 이상 기업은 연구개발 인원 수 대비 임직원 수 비율이 15% 이상이면 5점이고, 15인 미만 기업은 연구개발 인력 3인 이상이면 5점이다"],["연구개발비","최근 2년간 연구개발비가 매출총액 대비 10% 이상이면 7점을 받는다"],["동향 파악 및 활용","지식재산권 동향 파악 및 활용은 최근 2년간 선행기술조사와 특허맵 등으로 시장 동향을 파악하고 연구개발 방향 설정 시 특허정보로 회피설계를 하는지 평가한다"],["매출 비중","보유 특허권·실용신안권 적용 제품 매출액이 최근 2년 매출총액의 30% 이상이면 8점이다"],["실시권 등 활용","전용실시권·통상실시권 허여·유지 건수, 외부 지식재산권 도입 건수, IP 금융 이용, 지식재산 관련 인증 취득을 건당 1.6점으로 측정한다"],["분쟁 사전 점검","자사 제품의 타사 권리 침해 여부와 타사 제품의 자사 권리 침해 여부를 주기적으로 점검하는지 평가하며 특허공제 가입 시 2점이 가산된다"]]}],"29":[{"t":"tree","title":"지식재산권의 구분","root":"지식재산권","branches":[["무체재산권","특허권·실용신안권·디자인권·상표권 같은 산업재산권과 저작권, 영업비밀 등 신지식재산권을 아우르는 무체재산권이다"],["신지식재산권","영업비밀과 반도체 회로 배치 설계는 책에서 신지식재산권 갈래로 분류된다"]]},{"t":"table","title":"산업재산권의 보호 대상","head":["권리","보호 대상"],"rows":[["특허권","발명"],["실용신안권","고안"],["디자인권","디자인"],["상표권","상표"]]},{"t":"tree","title":"OODA 루프","root":"OODA 루프","branches":[["정의","관찰, 방향설정, 결정, 실행의 첫 글자를 딴 것으로 군사전략가 존 보이드가 개발한 전략 수립 방법이다 · 한 번에 끝나지 않고 실행 결과를 다시 관찰 단계로 돌려 각 단계를 반복하는 지속적 과정이다"],["관찰","기술 환경·소비자 요구·경쟁사 활동·법적 환경 등 외부와 지식재산 조직의 활동 같은 내부를 함께 살핀다"],["방향설정","환경 분석 정보를 걸러내고 분류하여 어떤 정보가 중요한지 선별하며 조직을 정렬하는 단계이다"],["결정","지식재산 전략의 핵심이며, 그 결과는 회사 전체 전략과 일치해야 하고 조직의 가이드라인이 된다"],["실행","보호할 이노베이션의 창출부터 시장에서 자산으로 활용되기까지의 전략 실행을 포괄한다"]]},{"t":"def","term":"통합적 지식재산 경영 전략","text":"기술혁신의 결과를 어떤 권리로 보호할지 정하고 권리를 취득·포트폴리오화·관리·활용하는 일련의 전략을 뜻한다 · 절대적인 것이 아니므로 기업의 실정과 법률적·경제적 환경에 맞게 창조적으로 적용해야 하며, 산업별로 중요한 권리도 다르다"}],"30":[{"t":"table","title":"특허와 영업비밀의 비교","head":["항목","특허","영업비밀"],"rows":[["존속","특허권의 존속기간은 설정등록된 날부터 출원일 후 20년이 되는 날까지이며, 만료되면 공공의 영역으로 들어가 누구나 쓸 수 있다 · 보호기간은 출원일 후 20년으로 한정된다","영업비밀은 비밀성이 유지되는 한 반영구적으로 이익을 누릴 수 있지만 일단 누구에게든 알려지면 영업비밀로서의 효용이 사라진다 · 비밀로 관리되는 한 기간 제한이 없다"],["보호조건","신규성·진보성·산업상 이용가능성이다","비공지성·경제적 유용성·비밀유지이다"],["보호대상","특허출원은 출원일로부터 1년 6개월이 지나면 그 내용이 공개된다","특허요건을 갖추지 못한 기술정보와 고객명부·판매계획 같은 경영정보도 보호대상에 포함한다"],["권리 발생","심사를 거쳐 설정등록되어야 독점배타적 권리가 생긴다","등록절차 없이 요건만 충족하면 인정된다"],["독자개발","타인이 특허 기술과 같은 기술을 독자적으로 개발하여 허락 없이 쓰면 특허권 침해이다","독자개발자에게 그것만으로 침해를 주장할 수 없다"],["공개와 실시","공개를 전제로 하며 실시권 설정이 가능하다","비공개를 전제로 하되 비밀유지를 조건으로 실시계약을 맺을 수 있다"]]},{"t":"vs","title":"유리한 경우","cols":[{"name":"특허가 유리","items":["침해사실 입증이 쉬운 경우","역공학으로 기술을 파악할 수 있는 경우에는 영업비밀보다 특허로 보호받는 편이 유리하다"]},{"name":"영업비밀이 유리","items":["공개되면 모방이 쉽고 침해 입증이 어려운 경우"]}]}],"31":[{"t":"table","title":"권리 조합","head":["항목","내용"],"rows":[["보호기간","보호기간 면에서는 갱신으로 반영구 보호가 가능한 상표권이 가장 유리하고, 저작권이 그다음이며, 특허·디자인·실용신안은 그 뒤를 따른다"],["방법 관련 기술","제조방법이나 사용방법 같은 방법 관련 기술은 특허나 영업비밀로 보호받는 것이 적절하다"],["하나의 장치","기술은 특허·실용신안, 외관은 디자인, 설계도면은 저작권, 드러나지 않는 노하우는 영업비밀로 겹쳐 보호하는 포트폴리오를 구축할 수 있다"],["상업화된 제품","제품·제조기술·사용방법은 특허로, 포장과 형상은 상표로, 역공학으로 분석하기 어려운 제조 노하우는 영업비밀로 보호할 수 있다"]]},{"t":"flow","title":"권리 형태의 전환","steps":["발명이 완성되면 영업비밀로 보호된다","특허출원·등록으로 특허권 보호로 바뀐다","특허출원은 출원일 후 18개월이 지나면 강제로 공개되므로 그 시점에 영업비밀로서의 생명이 다한다"]},{"t":"tree","title":"영업비밀과 특허출원","root":"특허출원","branches":[["일부 영업비밀","발명의 일부를 영업비밀로 남기려면 그 부분을 특허출원 명세서에 기재하지 않아야 한다"],["명세서","특허등록을 위해서는 해당 기술분야의 통상의 기술자가 명세서만 보고 쉽게 실시할 수 있을 정도로 기재하여야 한다"],["아스파탐","제조공정 특허가 1992년 만료된 뒤에도 뉴트라스위트라는 상표가 핵심 브랜드로 남아, 특허에서 상표 보호로 이어진 사례로 소개된다"]]}],"32":[{"t":"tree","title":"개방형 이노베이션","root":"개방형 이노베이션","branches":[["전략","기업 외부의 정보·지식·기술을 제품과 서비스 혁신에 활용하는 전략이다"],["주장자","개방형 혁신 전략을 처음 주장한 사람은 UC 버클리 하스 경영대학원의 헨리 체스브로 교수이다"],["리눅스","1998년 소프트웨어 소스 프로그램을 공개하여 자유로운 사용과 개선을 허용하고, 개량본도 동일 조건으로 무상 활용되게 한 개방형 이노베이션 사례이다"],["위키피디아","비영리 기관이 운영하고 콘텐츠는 사용자가 제작·편집하는 개방형 이노베이션 사례이다"],["마이스페이스와 유튜브","개방형 이노베이션 전략을 활용한 영리 기업의 대표적 사례로 제시된다"]]},{"t":"tree","title":"선행특허 전략","root":"선행특허 전략","branches":[["정의","R&D 성과가 나온 뒤 권리화하는 방식과 달리 특허 조사·분석으로 미래 기술을 예측하여 강한 특허를 먼저 확보한 뒤 이를 포트폴리오화하는 것이다"],["권리 확보","경쟁사가 확보하지 않은 공백기술이나 경쟁사가 쓸 수밖에 없는 핵심기술을 중심으로 권리를 확보한다"],["강한 특허권","원천특허·핵심특허·길목특허·표준특허가 제시된다"],["길목특허","경쟁사가 반드시 사용할 수밖에 없는 특허로, 기술이 뛰어나지 않고 비교적 단순해도 적은 비용으로 강력한 효과를 낼 수 있다는 장점이 있다"],["삼성전자","플래시 메모리 에너지 소비를 크게 줄이는 핵심특허를 확보한 뒤 침해소송을 제기하여 샌디스크와의 라이선스 재계약을 유리하게 맺었다"]]}],"33":[{"t":"vs","title":"영업비밀과 특허의 선택","cols":[{"name":"영업비밀이 유리","items":["특허 출원 공개가 경쟁 기업에 부당이득을 줄 수 있거나, 경쟁사가 모방할 가능성이 낮을 때는 영업비밀 보호가 선호된다","최종 제품만으로 구성 파악이 어려운 특수 제조공정 화학물질 등은 영업비밀로 보호하는 것이 효과적일 수 있다","기술 진보가 거의 없는 성숙 기술은 영업비밀로 유지하는 것이 효과적이다"]},{"name":"특허가 유리","items":["공정 발명은 경쟁이 심한 분야에서는 특허로 보호할 필요가 있다","같은 기능이지만 소스코드가 다른 프로그램의 개발을 막으려면 특허가 더 유리하다","특허는 출원공개로 모방 가능성이 높아 보호 강도가 약해질 수 있다"]}]},{"t":"table","title":"영업비밀의 한계","head":["항목","내용"],"rows":[["보호기간","영업비밀의 보호기간은 무한대인 반면 특허권은 설정등록일부터 출원일 후 20년이 되는 날까지로 유한하다"],["유지비용","영업비밀로 보호하려면 종업원에게 비밀유지 의무를 부여하고 보안을 철저히 해야 해서 유지비용이 특허확보 비용을 넘는 경우가 많다"],["라이선싱","영업비밀은 라이선시에게 공개해야 하는 과정에서 유출 위험이 있어 특허기술보다 라이선싱이 더 어렵다"],["투자유치","기술이 영업비밀로만 존재하면 투자유치가 어려우므로, 일부 기술이 특허로 등록되면 외부 투자자에게 신뢰성 높은 신호가 될 수 있다"],["저작권","목적코드의 복제를 막으려면 저작권이 더 유리하다"]]}],"34":[{"t":"def","term":"지식재산경영인증제도","text":"특허청이 지식재산 경영을 중소기업에 확산시키고 인증기업의 신뢰성을 높이려고 시행하는 제도이며, 지원 자격은 중소기업기본법상 중소기업이다"},{"t":"flow","title":"인증 절차","steps":["기업의 자가진단·신청","운영기관의 서류심사와 방문심사","특허청이 선정 여부를 결정"]},{"t":"table","title":"인증기업의 혜택","head":["혜택","내용"],"rows":[["우선심사·감면","인증기업은 특허·실용신안·디자인 우선심사 대상이 되며 연차등록료(4~9년차)를 70% 감면받는다"],["특허청 지원사업","특허청은 각종 지원사업 참여 시 인증기업에 가점을 부여하며, 대상에는 글로벌IP스타기업·IP바로지원 서비스·IP R&D 전략지원 사업 등이 포함된다"],["타 기관 혜택","인증기업은 중소벤처기업부의 혁신창업사업화자금 지원대상이 되고, 한국방송광고진흥공사의 방송광고 제작비 지원과 광고비 70% 할인, 서울보증의 보증한도 확대 등의 혜택도 받는다"]]}],"35":[{"t":"tree","title":"영업비밀의 성립","root":"영업비밀","branches":[["정의","공공연히 알려져 있지 않고 독립된 경제적 가치를 가지며 비밀로 관리된 생산방법·판매방법 등 영업활동에 유용한 기술상 또는 경영상의 정보이다"],["요건","비공지성, 경제적 유용성, 비밀관리성의 세 가지 요건을 갖추어야 한다"],["인정 사례","특허출원 공개 전이고 특허발명으로 인정될 정도의 신규성·진보성이 있는 자료로 실제 수익을 얻었다면 영업비밀로 인정될 수 있다"]]},{"t":"tree","title":"영업비밀 침해행위","root":"영업비밀 침해행위","branches":[["부정한 취득","절취·기망·협박 등 부정한 수단으로 영업비밀을 취득하고 사용하는 행위는 영업비밀 침해행위에 해당한다"],["비밀유지 의무 위반","계약관계 등으로 비밀유지 의무가 있는 자가 부정한 이익을 얻거나 보유자에게 손해를 입힐 목적으로 영업비밀을 사용·공개하는 행위도 침해행위이다"],["삭제·반환 거부","영업비밀 보유자의 삭제·반환 요구를 부정한 이익이나 손해 목적으로 거부하는 행위도 영업비밀 침해행위에 해당한다"]]},{"t":"vs","title":"손해배상","cols":[{"name":"종전 규정","items":["영업비밀 침해가 고의로 인정되면 손해액의 3배를 넘지 않는 범위에서 배상하도록 하였다"]},{"name":"2024년 8월 21일부터","items":["영업비밀 침해와 아이디어 탈취, 특허권 침해를 고의로 한 경우 손해액의 최대 5배까지 배상해야 한다"]}]},{"t":"table","title":"판단 사례","head":["사례","판단"],"rows":[["클라우드 저장","퇴사 후 사용할 목적으로 사내 보안시스템을 우회해 거래처 명단 등이 담긴 파일을 외부 클라우드에 저장한 것은 영업상 주요자산의 무단 반출로 인정되었다"],["양배추 부계원종","유전정보가 눈에 보이지 않아도 설계도 역할을 하므로 정보성이 인정되고, 이를 취득한 것은 영업비밀의 취득에 해당한다고 보았다"]]}],"36":[{"t":"tree","title":"연구개발 단계의 기술이전 목표","root":"연구개발 관리 전략","branches":[["지식재산 전략","공격적 지식재산 전략과 방어적 지식재산 전략에 따른 연구개발 전략을 설명할 수 있어야 한다"],["공공연구기관","연구개발 단계부터 기술이전·사업화 목표를 분명히 하고 수요기업의 니즈를 분석하며 상용화 가능한 원천형 또는 핵심기술을 창출해야 한다"],["연구개발 조직","기술이전에 유의한 영향을 준 변수를 주기적으로 모니터링하여 연구개발 추진에 반영하고 라이선스 관점을 연구개발 목표에 담아야 한다"]]},{"t":"tree","title":"라이선시의 관심","root":"라이선시(수요기업)","branches":[["주요 관심","라이선스 과정에서 대상 기술의 우수성과 특허의 강한 권리성이다"],["기술 우수성","라이선시 관점의 기술 우수성은 미래 전략사업에 쓸 수 있는 혁신성과 경쟁성을 뜻하며, 혁신 기술은 기존 기술을 대체하는 원천기술 확보로 이어질 수 있다"],["특허의 권리성","특허의 권리가 강할수록 라이선서는 독점적 지위와 협상력을 얻고, 기술이전 가능성이 높아지며 합리적 기술료 결정의 중요한 요인이 된다"]]}],"37":[{"t":"tree","title":"라이선스 관점의 기술기획","root":"라이선스 관점의 기술기획","branches":[["정의","공공 연구개발 단계부터 시장 니즈를 탐색하고 글로벌 기술개발 동향에 맞는 혁신 기술개발을 체계적으로 추진하도록 기획하는 것이다"],["전제","체계적 기술기획을 추진하려면 기획예산의 확보가 전제되어야 하며, 연구개발은 글로벌 기술개발 추세와 상대 경쟁력 분석에 근거해야 한다"],["실행 전략","기술개발 성과와 함께 원천(핵심) 특허를 적시에 확보할 수 있는 실행 전략이 필요하며, 라이선스 관점의 기술기획이 연구개발 단계에 체계적으로 반영되어야 한다"],["기초·원천형 기술","생명공학 같은 기초·원천형 기술개발은 장기간 활용 전략이 필요하며, 중간평가에 라이선스 관점의 평가항목을 추가해 다음 단계로 진입할 검증결과와 경쟁수준을 확인해야 한다"],["응용연구","응용연구 개발은 수요기업의 기존 기술과 보완 관계이거나 대체기술의 역할을 할 수 있어야 기술이전 성공가능성이 높아진다"],["성과 관리","연구개발 성과는 평가과정에서 시장의 기술적 니즈, 기술경쟁력 수준, 원천(핵심)특허 확보 여부 등을 확인하고 체계적으로 관리해야 한다"]]},{"t":"tree","title":"라이선스 관점의 기술마케팅","root":"라이선스 관점의 기술마케팅","branches":[["정의","수요기업군의 기술 니즈와 시장 경쟁상황에 근거해 기술흡수 및 사업화 역량이 상대적으로 높은 수요기업군을 선정한 뒤 맞춤형 기술개발로 기술이전을 수행하는 것이다"],["전략의 구성","기술이전 성공가능성에 영향을 주는 핵심변수를 기준으로 하는 대상기술의 탐색·선정과, 수요기업의 흡수역량·시장 지배력 등을 분석하는 수요기업 탐색으로 이루어진다"],["대상기술","연구개발기관의 기술모집단에서 기술이전 성공가능성에 영향을 주는 핵심변수를 기준으로 탐색하고 선정한다"],["선정 기준","기술의 완성도와 혁신성, 특허의 안정성, 시장의 성장성, 상용화 시점 등을 종합평점으로 고려할 수 있다"],["수요기업 탐색","산업·제품·기술·특허 분류에서 수요기업의 기술흡수역량, 제품군, 시장 지배력, 경쟁구조 등을 분석하는 방식으로 수행하며 결과에 따라 라이선시 대상기업의 우선순위를 정한다"]]}],"38":[{"t":"tree","title":"독점 IP 전략","root":"독점 IP 전략","branches":[["정의","공격적 IP 전략의 시장 지배력 행사는 특허를 외부에 라이선스하지 않고 공격적으로 집행하여 독점 시장에서의 우위를 지키는 것이며, 이를 독점 IP 전략이라 한다"],["기업 행동","독점 IP 전략으로 볼 수 있는 기업 행동에는 특허 장벽 구축, 공격적 차단, 공격적 덤불 구축이 있다"],["대상 발명","신약처럼 시장 지배력을 행사할 수 있는 상당한 시장 기회를 만드는 발명은 독점 전략의 대상이 될 가능성이 크다"],["비용","독점 IP 전략을 택하면 외부 라이선싱으로 얻을 수 있는 잠재 수익을 포기하고 권리 강화와 침해 소송에 드는 유지 비용을 감수해야 한다"]]},{"t":"tree","title":"특허 장벽","root":"특허 장벽(patent fence)","branches":[["정의","유사한 기능을 가지되 조금씩 다른 기술적 해법의 범위를 덮는 특허들로 구성한 특허 군을 말한다"],["출원 경향","기업은 핵심기술 주변 특허가 타 기업에 의해 회피 출원되는 것을 최소화하려고 서로 중첩되고 보완적인 특허권을 출원하는 경향이 있다"],["지속적 관리","한번 구축하면 끝나는 것이 아니라 갱신·재심사·대체 특허 확보 같은 지속적 관리 노력이 필요하며, 제약 산업의 약물 재제형 특허출원이 그 예이다"],["진보성 판단 기준","가치 높은 특허를 공개하여 심사관의 진보성 판단 기준을 높이면 경쟁 기업이 출원한 특허의 등록을 막을 수 있으며, 이러한 전략은 특허 경주와 맥락을 같이한다"]]},{"t":"tree","title":"IP 보호 선택","root":"보호 수단","branches":[["첫 전략적 의사결정","기업의 첫 전략적 의사결정은 특허·실용신안·저작권·상표권·영업비밀 중 어떤 IP로 기술을 보호할지 선택하는 것이며, 신약은 특허, 영화는 저작권, 공정혁신은 영업비밀로 보호하는 것이 합리적이다"],["특허의 공개","특허는 배타적 권리를 주지만 발명이 공개되므로 타 기업이 이를 개량하거나 후속 특허를 출원할 기회를 줄 수 있다"],["전통적 관점","전통적 관점에서는 특허는 공개를, 영업비밀은 비공개를 원칙으로 하여 양립할 수 없는 대체 관계로 보며, 영업비밀을 특허보호가 불가능할 때의 마지막 대안으로 본다"]]}],"39":[{"t":"cause","title":"독점 IP 전략의 한계","causes":["시장 가치의 감소","경쟁 기업의 혁신 인센티브 증가","네트워크 효과의 감소"],"result":"독점적 IP 전략은 장기적으로 기업에 이득이 되지 못할 수 있다"},{"t":"tree","title":"독점 전략의 한계","root":"독점 특허","branches":[["시장 가치","독점 특허로 시장 지배력이 커지면 경쟁 기업의 공동 마케팅이 줄어 점유율은 늘어도 시장 전체의 크기와 가치는 감소할 수 있다"],["회피 인센티브","독점적 기술의 IP를 가진 기업의 이윤이 늘수록 타 기업이 그 IP 주변 기술을 개발하여 회피하려는 인센티브도 증가한다"],["라이선싱","특허 장벽으로 경쟁자의 주변기술 개발을 막을 수 없고 그 주변기술이 시장 지배력을 줄일 수 있다면 특허를 외부로 라이선싱하는 편이 바람직할 수 있다"]]},{"t":"vs","title":"네트워크 효과","cols":[{"name":"직접적 네트워크 효과","items":["사용자 수에 따라 제품 가치가 증가하는 경우이다"]},{"name":"간접적 네트워크 효과","items":["보완재 시장을 통해 발생하는 효과이다"]}]},{"t":"def","term":"시장 지배력 행사","text":"강한 IP권리를 가진 기업은 네트워크 효과의 기회를 무시하고 IP로 인한 시장 지배력만 행사하려는 실수를 하기 쉬우므로 시장 지배력 행사는 신중해야 한다"}],"40":[{"t":"tree","title":"IP 이전과 중개","root":"IP 거래","branches":[["판매·이전","혁신자가 IP를 사업화할 제조·마케팅 역량이 부족하면 사업화 역량을 가진 타 기업에 IP를 판매·이전하는 것을 고려할 수 있다"],["정보 비대칭","구매자가 혁신 가치에 대한 정보를 제한적으로만 얻고 판매자는 유출 우려로 정보를 완전히 공개하지 않으려 해 정보 비대칭과 탐색 비용이 커진다"],["중개기관","높은 거래비용 때문에 기술 도입자와 제공자를 이어 주는 중개기관이 필요하며, 라이브 옵션·온라인 플랫폼·NPE·IP 브로커 등이 중개 역할을 한다"]]},{"t":"tree","title":"라이선싱 결정","root":"라이선싱","branches":[["소유권 유지","IP를 팔지 않고 소유권을 유지하면서 라이선스 계약을 맺는 방법이 있으며, 자체 사업화를 하지 않는다면 보완 자산을 가진 제3자에게 배타적 라이선싱을 하는 것이 합리적일 수 있다"],["비교","기업은 라이선싱 결정 전에 로열티 수익과 라이선싱으로 늘어나는 시장 경쟁 비용을 비교해야 하며, 시장 지배력이 큰 이익을 주는 상황에서는 보통 라이선스를 하지 않는다"],["표준화","기업의 특허 집중도와 활동도가 높을수록 표준화 과정에 참여하려는 경향이 낮아지는데, 표준에 포함되면 특허를 광범위하게 라이선스해야 하기 때문이다"],["경쟁 기업","더 효율적이고 사업화 자원을 갖춘 경쟁 기업이 있다면 라이선싱이 혁신 기업의 사업화 역량과 제품 수요를 늘려 주며, 바이오 창업 기업이 대형 제약사에 특허를 라이선스하는 경우가 많다"]]},{"t":"tree","title":"협력과 라이선스 계약","root":"기업 간 협력","branches":[["사례","질레트는 칼날과 면도기 손잡이의 접촉면 특허를 시장 표준으로 만들어 호환 손잡이를 싸게 팔고 칼날로 수익을 내는 전략을 썼고, 델 컴퓨터는 크로스 라이선싱으로 로열티 부담을 덜었다"],["협력의 이득과 한계","개발비용을 줄이고 분쟁을 미연에 방지할 수 있는 이득이 있으나 반독점법 등 법적 규제와 얽힐 수 있고, 다른 기업을 배제하면 사회 복지를 줄일 수도 있다"],["공동 표준 제정 기구","참여하면 제품 가치가 올라가고 네트워크 효과가 촉진되며 정보 비용이 줄지만, 일부 기업의 진입 장벽 상승이나 보유 IP에 유리한 개입이라는 부정적 면도 있다"],["그랜트백","라이선스 계약에서 특허권자가 라이선시에게 개량기술에 대한 실시권을 특허권자에게 제공하도록 요구하는 것을 그랜트백(grant back)이라 한다"]]},{"t":"def","term":"경고장과 소송","text":"독점적 IP를 가진 기업은 침해자에게 경고장을 보내거나 소송을 제기하여 침해 기업을 시장에서 퇴출시키거나 로열티를 확보하며, 실제 소송으로 이어지는 경우는 많지 않다"}],"41":[{"t":"vs","title":"공격적 전략과 방어적 전략","cols":[{"name":"공격적 IP 전략","items":["경쟁적 이점을 창출하려는 것이다"]},{"name":"방어적 전략","items":["경쟁적 약점이나 타 기업 특허로 로열티를 지불하는 상황을 막으려는 전략이다","방어적 전략에는 법적 조치, 대체 기술 개발, 라이선싱 및 구매, 방어적 특허풀 구축, 정보 공개가 있다"]}]},{"t":"tree","title":"법적 조치","root":"법적 조치","branches":[["수단","이의신청·재심사 청구·무효소송으로 타 기업 IP에 영향을 주는 방어책이며, 사업화에 필요한 IP 보유자가 확실해 불확실성이 제거된 상태에서 효과적이다"],["진입 기업의 방법","진입 기업은 기존 기업 IP의 유효성에 이의를 제기하거나, 유효성은 인정하되 자사 제품이 침해하지 않는다고 주장하는 두 가지 방법으로 법적 정당성을 확보할 수 있다"],["공공재","기존 IP를 무효화하면 소송비용을 분담하지 않은 다른 진입 기업도 비용 없이 시장에 진입할 수 있어 성공이 공공재가 되어 버린다는 단점이 있다"],["가치 있는 특허","이의신청과 재심사 분석 결과, 인용도와 청구항 수로 측정되는 가치 있는 특허가 법적 견제를 더 많이 받는 경향이 있다"]]},{"t":"tree","title":"대체 기술과 라이선싱","root":"회피와 라이선싱","branches":[["대체 기술","신규 기업은 기존 기업의 기술 요소를 회피할 수 있는 대체 기술을 개발할 수 있으며, 이때 경쟁이 치열해질 수 있고 회피 기술 개발의 비용과 성공확률을 계산해야 한다"],["기회비용","대체 기술이 기존 기술에 비해 기능적 장점이 없다면 IP를 회피하는 기술 개발은 사회적으로 낭비가 될 수 있어 라이선싱의 기회비용이 생긴다"],["라이선스의 합리성","신규 기업이 회피 기술 개발 역량이 있음을 기존 기업이 안다면 라이선스하는 것이 합리적이며, 라이선시는 침해 위험과 출시 시간을 줄이고 라이선서는 IP 유효성 도전과 낭비적 경쟁을 피한다"],["크로스 라이선싱","대규모 특허 포트폴리오의 크로스 라이선싱과 특허풀의 번들 라이선싱에는 미래 특허에 대한 사전적 크로스 라이선싱 조항이 포함될 수 있고, 시장 경쟁이 치열할 때 선호된다"],["고려 사항","신규 기업이 라이선싱을 고려할 때는 기존 기업의 라이선스 거부 가능성, 경쟁 기업 간 라이선스가 반독점법에 저촉될 위험, 대체 기술 부분 개발로 협상 우위를 점할 가능성을 살펴야 한다"],["매입·인수합병","기존 기업의 특허가 있는 시장에 진입하는 다른 대안은 해당 특허를 매입하거나 특허 보유 기업을 인수합병하는 것이며, 시스코가 이 전략으로 유명하다"]]}],"42":[{"t":"tree","title":"방어적 특허풀","root":"방어적 특허풀 구축 전략","branches":[["정의","거대한 특허 포트폴리오를 구축하여 상대의 침해 소송이나 홀드업에 맞소송으로 대응하는 것이며, 상호 홀드업이라고도 한다"],["장점","상호 홀드업은 기업 간 화해를 통한 빠른 해결을 가능하게 하며, 방어적 특허 포트폴리오를 가진 기업들은 서로 대규모 크로스 라이선스로 이어지는 경우가 많다"],["단점","대규모 특허 포트폴리오를 얻으려는 낭비적 경쟁, 곧 특허 군비 경쟁을 낳을 수 있다는 단점이 있다"],["한계","기술을 스스로 사업화하지 않는 개인 발명가·대학·NPE에는 무력한데, 이들은 맞소송 대상이 될 사업이 없어 상호 홀드업이 통하지 않기 때문이다"]]},{"t":"def","term":"정보 공개","text":"특허 침해 소송이 제기될 때까지 빠르게 잠재적 침해 기술 정보를 공개하여 제3자가 특허를 받지 못하게 하는 방어 전략이며, IBM이 기술 공개 저널을 낸 사례가 있다"}]};
